sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        var description = current.getValue('description') || '';
        if (!description) {
            return;
        }

        var engine = new x_2145749_qc.ComplaintTriageEngine();
        var orderValue = parseFloat(current.getValue('x_2145749_qc_order_value')) || 0;
        var result = engine.triage(description, orderValue);

        // Set urgency score
        current.setValue('x_2145749_qc_ai_urgency_score', result.urgency_score);

        // Set sentiment
        current.setValue('x_2145749_qc_ai_sentiment', result.sentiment);

        // Handle complaint_type: if user already set it, only override with a work_note
        var existingType = current.getValue('x_2145749_qc_complaint_type');
        if (!existingType || existingType === '') {
            // No user-provided type, set it from engine
            current.setValue('x_2145749_qc_complaint_type', result.complaint_type);
        } else if (existingType !== result.complaint_type) {
            // User set a type that differs from AI detection - log suggestion
            current.work_notes = '[AI Triage] Detected complaint type: "' + result.complaint_type +
                '" differs from user-selected: "' + existingType +
                '". Review may be warranted.';
        }

        // Update the record (after insert, we need an explicit update)
        current.update();

    } catch (e) {
        // Don't block case creation if triage fails
        gs.error('ComplaintTriageEngine: AI triage failed for case ' +
            current.getUniqueValue() + ' - ' + e.message);
    }
})(current, previous);
